using System.Text;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.Rendering;
using UnityEngine.SceneManagement;

public class FishLinePatch
{
    public static void Run()
    {
        StringBuilder sb = new StringBuilder();
        GameObject hook = GameObject.Find("World/Hook");
        LineRenderer line = hook != null ? hook.GetComponent<LineRenderer>() : null;

        if (line == null)
        {
            Debug.LogError("[FishLinePatch] World/Hook 上没有 LineRenderer");
            return;
        }

        GameObject rodAnchor = GameObject.Find("World/Rod/LineAnchor");

        line.startWidth = 1f;
        line.endWidth = 1f;
        line.widthMultiplier = 0.05f;
        line.numCapVertices = 2;
        line.numCornerVertices = 2;
        line.alignment = LineAlignment.View;
        line.shadowCastingMode = ShadowCastingMode.Off;
        line.receiveShadows = false;
        line.lightProbeUsage = LightProbeUsage.Off;
        line.reflectionProbeUsage = ReflectionProbeUsage.Off;
        line.useWorldSpace = true;
        line.positionCount = 2;

        if (rodAnchor != null)
        {
            line.SetPosition(0, rodAnchor.transform.position);
            line.SetPosition(1, hook.transform.position);
        }

        EditorUtility.SetDirty(line);
        Bounds bounds = line.bounds;
        sb.AppendLine("line size(" + bounds.size.x.ToString("0.000") + "," + bounds.size.y.ToString("0.000") + "," + bounds.size.z.ToString("0.000") + ")");

        for (int i = 0; i < SceneManager.sceneCount; i++)
        {
            Scene scene = SceneManager.GetSceneAt(i);

            if (scene.name != "Fishing" || !scene.isLoaded)
                continue;

            EditorSceneManager.MarkSceneDirty(scene);
            EditorSceneManager.SaveScene(scene);
            sb.AppendLine("scene saved");
        }

        Debug.Log("[FishLinePatch]\n" + sb);
    }
}
